SET LOCAL aidash.scope = 'deployment';
ALTER TABLE public.registry DISABLE TRIGGER marketplace_registry_fence;
UPDATE "registry" SET "metadata" = jsonb_set("metadata", '{config}', jsonb_set("metadata" -> 'config', '{provider}', '"openrouter"')) WHERE ("kind" = 'model') AND ("metadata" #>> '{config,provider}' IN ('openai_compatible')) AND (COALESCE("metadata" #> '{config,provider_credential}', 'null'::jsonb) = 'null'::jsonb AND COALESCE("metadata" #> '{config,plan_connection}', 'null'::jsonb) = 'null'::jsonb);
UPDATE "registry" SET "metadata" = jsonb_set("metadata", '{config}', jsonb_set("metadata" -> 'config', '{provider}', '"openai"')) WHERE ("kind" = 'embedding') AND ("metadata" #>> '{config,provider}' IN ('openai_compatible')) AND (COALESCE("metadata" #> '{config,provider_credential}', 'null'::jsonb) = 'null'::jsonb AND COALESCE("metadata" #> '{config,plan_connection}', 'null'::jsonb) = 'null'::jsonb);
ALTER TABLE public.registry ENABLE TRIGGER marketplace_registry_fence;
UPDATE "registry_requests" SET "request" = jsonb_set("request", '{config}', jsonb_set("request" -> 'config', '{provider}', '"openrouter"')) WHERE ("request" ->> 'kind' = 'model') AND ("request" #>> '{config,provider}' IN ('openai_compatible')) AND (COALESCE("request" #> '{config,provider_credential}', 'null'::jsonb) = 'null'::jsonb AND COALESCE("request" #> '{config,plan_connection}', 'null'::jsonb) = 'null'::jsonb);
UPDATE "registry_requests" SET "request" = jsonb_set("request", '{config}', jsonb_set("request" -> 'config', '{provider}', '"openai"')) WHERE ("request" ->> 'kind' = 'embedding') AND ("request" #>> '{config,provider}' IN ('openai_compatible')) AND (COALESCE("request" #> '{config,provider_credential}', 'null'::jsonb) = 'null'::jsonb AND COALESCE("request" #> '{config,plan_connection}', 'null'::jsonb) = 'null'::jsonb);
